Definition iv_disjoint (p q : word * word) : Prop := ltac2:(Rpl.RP.run_k (rplG ()) 2 "S5;A1;o3;Y6;00;A1;i74;#0;A2;i73;#1;#1;A2;k2;#0;A3;k78;#1;#1;r2;A2;k2;#0;A3;k78;#1;#1;r1;Lp;R#2;Lq;R#2;A2;i84;A2;k11;A2;k9;#3;A2;k2;#0;A3;k80;#1;#1;r2;#4;A2;k11;A2;k9;#4;A2;k2;#0;A3;k80;#1;#1;r1;#3;").
Inductive seps : list (word * word) -> Prop :=
| seps_nil : seps []
| seps_cons : forall p l, Forall (iv_disjoint p) l -> seps l -> seps (p :: l).

Fixpoint sum_sizes (l : list (word * word)) : Z :=
  match l with [] => 0 | iv :: r => bv_unsigned (snd iv) + sum_sizes r end.

Definition cfg_of (SEGS : list Segment) (R : bvmap 5 word) (p : Z) (M : word -> option byte) (model : Model) : config := ltac2:(Rpl.RP.run_k (rplG ()) 5 "S3;A1;o3;Y6;00;A1;i74;#0;Y3;0;LSEGS;RA1;i35;i85;LR;RA2;k86;A1;o3;Y2;1;#1;Lp;Ri5;LM;RP~R#1;A1;i87;A1;i74;A1;o3;#2;Lmodel;Ri88;A2;o89;A5;k90;k91;r4;A2;k92;#0;r3;r2;A1;k93;r5;r1;").

Section Sound.
Variable SEGS : list Segment.
Variable scfg : SpuriousCfg.
Variable IT : itab.
Hypothesis IT_ok : itab_sound SEGS IT.
Variable A : atable.
Variable nx0 : nat.
Variable LIMIT : Z.
(* the run's CONFIG_RSEQ flag as 0 or 1 ([APCK.rseq_z]): the auxv's size is in
   the plan's string expressions through [node_pnscan] / [node_layout], so
   [x_stmt] takes it too *)
Variable rz : Z.
Variable HS : nat -> option acs.

Variable XN : nat -> list expr -> acs -> option acs.
Variable XE : nat -> list expr -> acs -> option (Z * list spiece * acs).
Variable XB : nat -> list expr -> acs -> option (acs * acs).

Hypothesis SEGS_wx : wx_segs_nowrap SEGS.
Hypothesis SEGS_in_hull : forall a : word, in_hull A (bv_unsigned a) = false -> find_segment SEGS (bv_unsigned a) 1 = None.

Definition res_len_ok : Prop := ltac2:(Rpl.RP.run_k (rplG ()) 0 "S1;A1;i74;A1;o3;Y6;00;A3;i15;i94;A2;k95;A2;i73;#0;#0;A1;k96;vSEGS;A1;k97;vA;").
Definition hull_ok : Prop := ltac2:(Rpl.RP.run_k (rplG ()) 0 "S3;A1;k82;vA;A1;o8;Y12;000;A1;k83;vA;A2;i19;A2;k11;o12;#0;A2;i19;A3;i15;i5;A2;k16;#0;#1;o12;A2;i19;A3;i15;i5;A2;k16;#2;#1;o12;A2;k11;#2;k98;").
Definition shadow_ok : Prop := ltac2:(Rpl.RP.run_k (rplG ()) 0 "S2;A1;k99;vA;Y1;0;A2;i19;A2;k11;o12;#0;A2;k11;#0;A2;k100;A1;o8;#1;A1;o8;Y5;0f;").
Hypothesis RES_len : res_len_ok.
Hypothesis RES_hull : Forall (fun iv => img_lo A <= bv_unsigned (fst iv) /\ bv_unsigned (fst iv) + bv_unsigned (snd iv) <= img_hi A) (segments_reserved SEGS).
Hypothesis HULL_ok : hull_ok.
Hypothesis SHADOW_ok : shadow_ok.

Variable SINV : env -> (word -> option byte) -> Prop.
Variable argH : env -> word -> bool.

Hypothesis argH_high : forall E (a : word), argH E a = true -> CEIL <= bv_unsigned a /\ uE E e_sp0 <= bv_unsigned a.

Hypothesis e_sp0_init : expr_vars_lt nx0 e_sp0 = true.
Hypothesis argH_agree : forall E E' (a : word), env_agree nx0 E E' -> argH E a = argH E' a.
Hypothesis SINV_frame : forall E M M', (forall a, argH E a = true -> M' a = M a) -> SINV E M -> SINV E M'.
Hypothesis SINV_agree : forall E E' M, env_agree nx0 E E' -> SINV E M -> SINV E' M.

Variable HOLES : nat -> env -> Fs.Fs -> TSet.
Hypothesis HOLES_agree : forall h E E' fs, env_agree nx0 E E' -> HOLES h E fs = HOLES h E' fs.
Hypothesis HOLES_nil : forall h E fs, HOLES h E fs [].

Hypothesis HOLES_flat : forall h h' E E' fs, HOLES h E fs = HOLES h' E' fs.

Variable FS0 : Fs.Fs.

Variable KC : nat.

(** THE LAUNCH'S EXTRA RESERVED INTERVALS.  [State.init_model] seeds
    [vm_reserved] with the image's reservations AND with what the kernel maps
    for the process besides the image: the vvar pages and the vDSO text, taken
    as one unhinted [get_unmapped_area] span, which a top-down layout answers
    from the gap just below [mm->mmap_base].

    [co_res] used to read [vm_reserved ... = segments_reserved SEGS], which
    ASSERTED that there is nothing else in the ledger.  A consumer could then
    conclude that a region ABOVE the image hull meets no reserved interval, and
    the pair sits exactly there, so a plan node could certify a grant
    overlapping the vDSO.  The existential below says the same thing without
    that assertion: the image's reservations, then a list [rx] the launch adds,
    of which the consumers need the geometry, the count and the total size.

    The two checker-side numbers are [n_resx A] and [resx_bytes A]: UPPER
    bounds, 0 for a launch that reserves nothing extra.
    Model donor [75d69e00:theories/Common/AsanPlanSound.v:178-204]. *)
Definition resx_entry_ok (iv : word * word) : Prop :=
  0 < bv_unsigned (snd iv)
  /\ bv_unsigned (fst iv) mod 4096 = 0
  /\ bv_unsigned (snd iv) mod 4096 = 0
  /\ img_hi A <= bv_unsigned (fst iv)
  (** a PAGE clear of [KHI]: a FIXED range ending at or below [KHI]
      ([APCK.resx_clear]) meets none of them *)
  /\ KHI + 4096 <= bv_unsigned (fst iv)
  (** NOT [<= CEIL].  The pair hangs off [mm->mmap_base], and
      [Run.valid_mmap_base] admits a base up to [State.mmap_base_max] =
      0x7ffff8000000, above [AsanCeil.alloc_ceiling]. *)
  /\ bv_unsigned (fst iv) + bv_unsigned (snd iv) <= 2 ^ 47.

#[local] Notation CHECK := (APK.check SEGS IT A nx0 LIMIT rz XN XE XB HS KC).

#[local] Notation cfg := (cfg_of SEGS).

