Lemma forget_sound : forall E cs R FULL model ixs,
  cs_ok E cs R FULL model -> cs_ok E (set_kn cs (drop_ixs ixs 0 (kn cs))) R FULL model.
Proof. ltac2:(Rpl.RP.run_k (rplG ()) 0 "S11;A1;i74;A1;o3;Y6;00;Y3;0;A3;k330;r2;o32;A1;k262;r6;P~Rr1;pA1;i35;r2;Px;Rr4;P~RA3;k172;r5;r1;r3;A1;r5;r2;P~RPx;Rr3;P~RA3;k172;r4;r1;r2;A1;r4;r2;A3;i173;r4;r3;r2;A1;k262;r9;A3;k302;vSEGS;r11;A4;k258;r11;r10;r7;r8;A1;k262;r10;A1;k262;r11;LE;Ri0;Lcs;Ri112;LR;RA2;k86;A1;o3;Y2;1;#0;LFULL;RP~R#0;A1;i87;A1;i74;A1;o3;#1;Lmodel;Ri88;Lixs;RA1;i35;i94;LHC;RA5;i203;r6;r5;r4;r3;r2;A8;k310;r7;r6;r5;r4;r3;#2;r1;cdEH;RLA;RtLP;R#3;Ll;R#4;m19;RNL~RA2;i19;P~RA3;i173;r3;r2;r1;#5;#6;P~R#5;A3;i173;r5;r4;r3;A3;k175;r3;r2;r1;1;L~RP~RA3;i173;r3;r2;r1;#5;L~RP~RPx;Rr4;P~RA3;k172;r5;r1;r3;A1;r5;r2;A3;i173;r5;r4;r3;r1;PA;RtPP;R#3;Pl;R#4;#6;A4;r1;i301;A3;k302;vSEGS;r8;A4;k258;r8;r7;r4;r5;A3;k330;r3;o32;A1;k262;r7;LK;Ri301;LHin;RA3;k172;i301;r1;A3;k330;r4;o32;A1;k262;r8;EHin;RA5;k333;r5;o32;#7;r2;r1;A3;k172;i301;r2;#7;A6;k176;P~RA3;i173;i301;#8;#9;Px;Ri301;P~RA3;k172;i301;r1;A1;k262;r12;A4;k302;vSEGS;r14;A4;k258;r14;r13;r10;r11;r2;P~RPx;Ri301;P~RA3;k172;i301;r1;#10;A4;k302;vSEGS;r13;A4;k258;r13;r12;r9;r10;r2;A3;i173;i301;A3;k302;vSEGS;r12;A4;k258;r12;r11;r8;r9;#10;A3;k175;i301;#8;#9;A6;k312;r11;r10;r9;r8;r7;r5;r3;r1;A4;k257;vSEGS;r7;A4;k258;r7;r6;r3;r4;#2;").
