Definition kfoot (E : env) (K : kentry) : option (Z * Z) := ltac2:(Rpl.RP.run_k (rplG ()) 2 "S5;A2;i73;i5;i5;A2;k335;r5;r3;A2;o166;#0;A4;o109;i5;i5;A2;k335;r4;r2;A2;k336;r4;r1;A2;o166;#0;A4;o109;i5;i5;#1;A2;k336;r5;r2;A1;o49;#0;LE;Ri0;LK;Ri301;m301;RNLK;Ri301;A1;i87;#0;r1;10;La;Ri334;Lw;Ri94;Lv;Ri1;A2;o166;#0;A4;o109;i5;i5;#1;A1;k156;r2;La;Ri334;Ll;Ri1;#2;La;Ri334;Ll;Ri1;Lk;Ri94;#3;Llo;Ri5;Lhi;Ri5;A2;o166;#0;A4;o109;i5;i5;r2;A2;k72;r1;r2;Le;Ri1;Lm;Ri5;#4;Le;Ri1;Llo;Ri5;Lhi;Ri5;#4;La;Ri334;Ln;Ri1;#2;La1;Ri334;Ln1;Ri1;La2;Ri334;Ln2;Ri1;#4;La;Ri334;Ll;Ri1;Lc;Ri5;#3;La;Ri334;Ll;Ri1;#2;").

Definition kfoot_apart (E : env) (K : kentry) (lo n : Z) : Prop := ltac2:(Rpl.RP.run_k (rplG ()) 4 "S0;LE;Ri0;LK;Ri301;Llo;Ri5;Ln;Ri5;m87;RNLx;RA1;i87;A2;i73;i5;i5;pA2;k337;r4;r3;2;Lp;RA2;i73;i5;i5;m73;RNLp;RA2;i73;i5;i5;pr1;1;Ls;Ri5;Ll;Ri5;A2;i84;A2;k11;A2;k9;r2;r1;r5;A2;k11;A2;k9;r5;r4;r2;i183;").

Lemma kentry_keep_sem : forall E M M' K lo n,
  kentry_ok SEGS E M K -> kfoot_apart E K lo n ->
