Lemma hole_only_eq : forall D E fs a b, hole_only a = true -> hole_only b = true -> t_eq (sd D E fs a) (sd D E fs b).
Proof. ltac2:(Rpl.RP.run_k (rplG ()) 0 "S3;A3;i15;i61;A1;k683;r2;o62;A3;vHOLES;o32;r6;r5;A4;k657;r7;r6;r5;r3;LD;Rk653;LE;Ri0;Lfs;Rk243;La;Ri654;Lb;Ri654;LHa;R#0;LHb;R#0;A5;k684;A4;k657;r7;r6;r5;r4;#1;#2;A5;k687;r7;r6;r5;r4;r2;A3;k688;#2;#1;A5;k687;r7;r6;r5;r3;r1;").
Qed.

Lemma salt2_vars : forall b x y, shape_vars_lt b x = true -> shape_vars_lt b y = true -> shape_vars_lt b (salt2 x y) = true.
Proof.
  intros b x y Hx Hy. unfold salt2.
  destruct x; destruct y; cbn [shape_vars_lt] in *; rewrite ?Hx, ?Hy; try reflexivity; try assumption.
Qed.

